-- Review on an approved nonproduction database first. Standalone operator script, not an automatic seed.
-- Updates only titles with exactly one current row, and only when all stock fields still match.
-- The default ROLLBACK previews the exact affected UUIDs. An authorized operator can explicitly COMMIT
-- after capturing a safe rollback record of the approved rows and checking the result in this transaction.
BEGIN;
WITH expected(title, old_content, old_source, old_keywords, old_priority, new_content, new_source) AS (
  VALUES
  ('VSU SmartMap Assistant identity and creator', 'VSU SmartMap Campus Assistant is part of the VSU SmartMap Web project. It helps students, visitors, and staff find buildings, offices, rooms, dormitories, food areas, landmarks, events, and other campus facilities. If asked who created the project or assistant, answer that it was created and developed by Vj F. Mabansag, a Third Year BS Computer Science student at Visayas State University. Keep this answer short and non-technical unless the user asks for technical details.', 'seed:campus-assistant-prompt', ARRAY['smartmap','assistant','creator','vj mabansag','project','campus map','chatbot']::text[], 100, 'Campus SmartMap is an unofficial student-led project created by Vj F. Mabansag. It covers the Visayas State University Main Campus in Visca, Baybay City, Leyte. The app helps users find campus locations and selected events and listings; it is not an official university service.', 'seed:campus-assistant-prompt'),
  ('VSU SmartMap location matching rules', 'When a user asks for a campus location, match exact or near-exact facility names, common shortened names, building codes, rooms, and categories. Examples: Admin may mean Administration Building; CR may mean comfort room or restroom; canteen, kainan, or food court may refer to dining facilities; clinic may refer to the infirmary or health facility; gym may refer to the gymnasium. If a query is ambiguous, give up to 6 likely options and ask a focused clarification.', 'seed:campus-assistant-prompt', ARRAY['location search','facility matching','rooms','building codes','cr','canteen','gym','clinic','admin']::text[], 96, 'Map cards use exact retrieved facility identifiers and names. A room card is tied to the retrieved parent building only when the room is present in its room list. A similar name or building-code match is not proof of a room location. Use Map & Directions for official visitor information, and use SmartMap records for app pins.', 'https://www.vsu.edu.ph/support/map'),
  ('VSU SmartMap room code and subject code guidance', 'If the user asks for a specific room code such as ICT101, CAS-201, or Lab A, search for the parent building that contains that room and say the room is inside that building. If the user asks for something that looks like a subject or course code, such as CSci 108 or G067, clarify that it may be a subject code and ask the user to check the Room Assignment in their schedule or COR.', 'seed:campus-assistant-prompt', ARRAY['room code','subject code','course code','cor','schedule','room assignment','ICT101','CSci']::text[], 95, 'A room code is mapped only if it explicitly appears in the retrieved rooms for a verified building. An unrecognized code does not establish a building. Subject codes identify classes; the official Room Assignment in the schedule or Certificate of Registration identifies the venue. Private schedules belong in the official student portal or with the instructor.', 'seed:campus-assistant-prompt'),
  ('VSU SmartMap directions and route limits', 'The map can show campus locations and route options inside the VSU campus area. The chat assistant should not invent exact turn-by-turn instructions, live GPS movement, or precise ETA from text alone. If the user wants navigation, tell them to open the Map tab, select the destination pin, and use Directions. If live location is unavailable or outside campus, use a manual start pin inside the VSU campus map.', 'seed:campus-assistant-prompt', ARRAY['directions','route','pathfinding','gps','manual start pin','navigation','map tab','eta']::text[], 94, 'SmartMap can offer route options from a verified map destination through its Directions control. A manual start can be used when available. Chat does not compute a live route, walking time, or accessibility status. The official VSU Map & Directions page is a separate reference for visitors to the Baybay Main Campus.', 'https://www.vsu.edu.ph/support/map'),
  ('VSU SmartMap emergency and security guidance', 'For urgent security, safety, medical, or emergency concerns, do not rely only on the chatbot. Direct the user to nearby guards, guard house or entrance facilities if available in the map, the VSU Infirmary for health concerns, and official university or local emergency channels. Keep the response short and action-oriented.', 'seed:campus-assistant-prompt', ARRAY['emergency','security','guard','guard house','infirmary','medical','safety','help']::text[], 93, 'For an urgent safety or medical issue, use on-site security or local emergency services directly. A map listing does not establish current staffing, emergency availability, opening hours, or access. Published VSU campus-access rules can require visitor identification; verify current entry instructions with VSU and do not share identity documents in chat.', 'https://www.vsu.edu.ph/university-policies-2?start=12'),
  ('Visayas State University overview and main contact', 'Visayas State University is located in Visca, Baybay City, Leyte, Philippines 6521. VSU describes itself as a leading global university in agriculture and allied fields, with its flagship main campus in Baybay City. Main contact details from the official website: trunkline +63 (53) 565 0600, fax +63 (53) 563 7067, and email uimpa@vsu.edu.ph.', 'https://www.vsu.edu.ph/about', ARRAY['vsu','visayas state university','contact','address','baybay','leyte','trunkline','uimpa']::text[], 92, 'The main campus of Visayas State University is in Visca, Baybay City, Leyte 6521, Philippines. The university website lists +63 (53) 565 0600 as a general trunkline, not an emergency number. For current office contacts or visitor access, check the official VSU site. Source reviewed 2026-11-27.', 'https://www.vsu.edu.ph/'),
  ('VSU main campus land area and facilities', 'VSU Main Campus covers about 1,099.4 hectares, extending from the shore of Camotes Sea to Mt. Pangasugan. Official VSU information lists 188 main-campus buildings, including student dormitories, staff houses, academic buildings, administration buildings, Main Library, Student Union, Convention Center, Center for Continuing Education, Infirmary, Guesthouse, Hostel, Pavilion, market, cafeteria, gymnatorium, marine laboratory, workshops, research and training centers, and other facilities.', 'https://www.vsu.edu.ph/about/overview', ARRAY['campus facilities','main campus','land area','camotes sea','mt pangasugan','buildings','dormitories','library','infirmary']::text[], 90, 'The VSU Main Campus is in Baybay City, Leyte. Historic campus descriptions include land-area and building counts, but are not a current facility or room inventory. Use the retrieved SmartMap record for app locations and the official Map & Directions page for visitor orientation. Source reviewed 2026-11-27.', 'https://www.vsu.edu.ph/support/map'),
  ('VSU undergraduate programs at Main Campus', 'VSU Main Campus undergraduate offerings include programs under Agriculture and Food Sciences, Humanities and Social Sciences, Natural and Mathematical Sciences, Computing, Teacher Education, Engineering, Forestry and Environmental Sciences, Management and Economics, Nursing, and Veterinary Medicine. Examples include BS Agriculture, BS Development Communication, BS Food Technology, AB English Language Studies, AB Philosophy, BS Biology, BS Computer Science, teacher education programs, engineering programs, BS Forestry, BS Environmental Science, BS Agribusiness, BS Economics, BS Hospitality Management, BS Tourism Management, BS Nursing, and Doctor of Veterinary Medicine.', 'https://www.vsu.edu.ph/admission/college', ARRAY['undergraduate programs','main campus','bs agriculture','bs computer science','engineering','nursing','veterinary medicine','education']::text[], 88, 'VSU publishes admissions and program information by campus and intake. Confirm the academic year, eligibility, and availability with the current official admissions page and admission portal; prior program lists are not a guarantee of current offerings. Source reviewed 2026-11-27.', 'https://cat.vsu.edu.ph/'),
  ('VSU component campus undergraduate programs', 'VSU component campuses offer selected undergraduate programs. Alangalang includes Elementary Education, Agriculture, Environmental Science, Information Technology, and Secondary Education. Isabel includes English Language Studies, Elementary Education, Physical Education, Agribusiness, Civil Engineering, Industrial Engineering, Information Technology, Mechanical Engineering, and Secondary Education. Villaba includes Elementary Education, Physical Education, Agriculture majors, and Secondary Education. Tolosa includes Elementary Education, Physical Education, Criminology, Fisheries, Industrial Security Management, Marine Biology, and Secondary Education.', 'https://www.vsu.edu.ph/admission/college', ARRAY['component campuses','alangalang','isabel','villaba','tolosa','undergraduate programs']::text[], 87, 'Alangalang, Isabel, Tolosa, and Villaba are separate VSU campuses; the Baybay SmartMap does not provide directions to their buildings. Confirm a program by campus and academic year through the official admissions portal. Source reviewed 2026-11-27.', 'https://cat.vsu.edu.ph/'),
  ('VSU College Admission Test basics', 'For VSUCAT, official VSU admission information says the admission rating is computed as 70% VSUCAT score and 30% GPA. Applicants generally need a final admission rating of at least 60% and must be within the approved quota of the chosen degree program. Equity Target Group, athlete, and artist applicants may qualify from 40% to below 60%, subject to ranking, slots, and document verification. Requirements and schedules change, so direct applicants to the official VSU admissions page for current details.', 'https://www.vsu.edu.ph/admission', ARRAY['vsucat','admission','college admission test','gpa','quota','equity target group','applicants']::text[], 86, 'The official VSU admissions portal publishes current applicant instructions for the VSU College Admission Test. Dates, eligibility, ratings, quotas, and documentary requirements depend on the published admission cycle. Check the campus and intake in the official portal; do not rely on an undated rule or estimate admission. Source reviewed 2026-11-27.', 'https://cat.vsu.edu.ph/'),
  ('VSU enrollment process for incoming students', 'VSU introduced a one-stop shop enrollment process for incoming students to reduce long queues and confusion. The official guide includes setting an online appointment before going to the enrollment site, attending a short guidance counselor intake session, bringing one long white folder, and submitting original admission requirements to the Admissions Office. Incomplete submissions may not be accepted, except some conditional cases noted by VSU. Always check the latest official #EnrollAtVSU page for current schedules and document lists.', 'https://www.vsu.edu.ph/admission/college/enrollment-process', ARRAY['enrollment','enroll at vsu','incoming students','appointment','admissions office','requirements','guidance counselor']::text[], 86, 'VSU posts enrollment instructions through official announcements and admission channels. Check the current academic year, intake, and campus before relying on an appointment process, dates, requirements, or fees. Use the official portal or campus office for personal enrollment. Source reviewed 2026-11-27.', 'https://www.vsu.edu.ph/13-announcements-main'),
  ('VSU Office of the University Registrar contact', 'For registrar concerns, official VSU program pages list the Office of the University Registrar at the Administration Building, Visayas State University. The undergraduate programs page lists Mr. Raymund Igcasama as University Registrar, telephone +63 53 563 7428, and email registrar@vsu.edu.ph. Another official contact page lists Office of the Registrar phone numbers +63 53 335 2644 / 563 7428. For records, enrollment, registration, and credentials, tell users to contact the Registrar directly.', 'https://www.vsu.edu.ph/admission/college', ARRAY['registrar','office of the university registrar','records','registration','credentials','enrollment','raymund igcasama']::text[], 85, 'The Office of the University Registrar handles academic records and related credentials. Use the official Registrar guidance and VSU document-request portal at https://docrequest.vsu.edu.ph/ for authorized services. Confirm the correct office/campus through VSU before visiting; do not share grades, student IDs, credentials, payment data, or documents in chat. Source reviewed 2026-11-27.', 'https://www.vsu.edu.ph/vsu/987-registrar-concerns'),
  ('VSU Learning Commons Library hours and services', 'VSU Learning Commons Library hours from its official site: weekdays 7:00 AM to 6:00 PM with no noon break; Saturdays 8:00 AM to 5:00 PM with noon break from 12:00 PM to 1:00 PM; term breaks and summer terms Monday to Friday 8:00 AM to 5:00 PM with no noon break. The library supports academic and research needs with books, journals, digital resources, multimedia materials, quiet study areas, collaborative spaces, computer labs, and staff assistance.', 'https://library.vsu.edu.ph/home.php', ARRAY['library','learning commons','library hours','books','journals','study area','computer lab','research']::text[], 84, 'The VSU Learning Commons website provides information on library services and posted schedules. Some official materials differ on Saturday hours; do not use an undated schedule to say the library is open now. Check the current term notice or official contact page at https://library.vsu.edu.ph/about-us/contact-us before visiting. Source reviewed 2026-11-27.', 'https://library.vsu.edu.ph/'),
  ('VSU portals: my.VSU and e-learning', 'The official VSU site describes my.VSU as a student portal for grades, subjects, schedules, and more. Some VSU pages also refer to the VSU E-Learning Portal as a resource for course requirements and helpful materials. If a student asks about grades, subjects, schedules, or room assignments, advise them to check my.VSU or official class/instructor announcements.', 'https://www.vsu.edu.ph/', ARRAY['my.vsu','student portal','grades','subjects','schedule','e-learning','room assignment']::text[], 83, 'The VSU site links my.VSU at https://my.vsu.edu.ph/ for a student’s grades, subjects, and personal schedule. Verify a room assignment in that portal or with the instructor. Do not share login credentials, identifying details, grades, or a private schedule in the map chat. Source reviewed 2026-11-27.', 'https://www.vsu.edu.ph/'),
  ('VSU official website and latest news', 'The official VSU website is https://www.vsu.edu.ph. It carries university news, announcements, academic information, admissions, student resources, transparency information, and links to services such as my.VSU. Recent official website content noted VSU entering the 2026 QS World University Rankings and other university news. For time-sensitive updates, direct users to the official website instead of guessing.', 'https://www.vsu.edu.ph/', ARRAY['official website','news','announcements','qs world university rankings','vsu.edu.ph','latest']::text[], 81, 'The official VSU website publishes university news, announcements and links to campus services. For current closures, events, dates or deadlines, check the latest dated notice and the specific campus, not an older search result. Source reviewed 2026-11-27.', 'https://www.vsu.edu.ph/')
), candidates AS (
  SELECT actual.id, actual.title, actual.updated_at, count(*) OVER (PARTITION BY actual.title) AS copies
  FROM public.ai_knowledge_entries AS actual
  JOIN expected ON expected.title = actual.title
)
UPDATE public.ai_knowledge_entries AS existing
SET content = expected.new_content, source = expected.new_source
FROM expected, candidates
WHERE existing.id = candidates.id
  AND candidates.title = expected.title
  AND existing.title = expected.title
  AND existing.updated_at IS NOT DISTINCT FROM candidates.updated_at
  AND candidates.copies = 1
  AND existing.content = expected.old_content
  AND existing.source IS NOT DISTINCT FROM expected.old_source
  AND existing.keywords IS NOT DISTINCT FROM expected.old_keywords
  AND existing.priority = expected.old_priority
RETURNING existing.id, existing.title, existing.is_active;
ROLLBACK;
